JOIN public.constituencies c ON c.canonical_code = m.ac_code
JOIN public.constituency_versions cv ON cv.constituency_internal_id = c.internal_id AND cv.is_current = true
JOIN public.parliamentary_constituencies pc ON pc.code = m.pc_code
JOIN public.parliamentary_constituency_versions pcv ON pcv.pc_id = pc.id AND pcv.is_current = true
ON CONFLICT (assembly_constituency_version_id, parliamentary_constituency_version_id, delimitation_regime_id, effective_from) DO UPDATE SET
  is_current = EXCLUDED.is_current,
  data_status = EXCLUDED.data_status,
  updated_at = now();

